    visited = [[False] * cols for _ in range(rows)]
    island_count = 0

    def dfs(x, y):
        if grid[x][y] == 0:
            return False

        if visited[x][y]:
            return True

        visited[x][y] = True
        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny] == 1:
                if dfs(nx, ny):
                    island_count += 1
                    break

        return island_count

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                island_count += 1

    return island_count

